  'cs.programme_created': 'പരിപാടി സൃഷ്ടിച്ചു',
  'cs.rubrics_help': 'നിങ്ങളുടെ സ്വന്തം റേറ്റിംഗ് സ്കെയിലുകൾ. നിങ്ങൾ പരിശീലിപ്പിക്കുന്ന കായിക ഇനങ്ങളുടെ സ്റ്റാൻഡേർഡ് സ്കെയിലുകൾ (FIFA, ICC, ഒളിമ്പിക് …) നിങ്ങൾക്കായി ചേർക്കപ്പെടും — അവ മാറ്റാം, ചേർക്കാം അല്ലെങ്കിൽ ആർക്കൈവ് ചെയ്യാം. ഒരു റൂബ്രിക്ക് പല ഇനങ്ങൾക്കും ബാധകമാകാം, ഒരു ഇനത്തിന് പല റൂബ്രിക്കുകളും ഉണ്ടാകാം. ഓരോ സ്കോറും നൽകിയ പതിപ്പിനൊപ്പം നിലനിൽക്കും; വ്യത്യസ്ത സ്കെയിലുകളിലെ സ്കോറുകൾ ഒരിക്കലും കലർത്തുകയോ ഔദ്യോഗിക സ്ഥിതിവിവരക്കണക്കാക്കുകയോ ചെയ്യില്ല.',
